-- Nekoweb Go backend business schema.
-- IDs are generated by the application so the schema does not require pgcrypto.
-- User credentials and agent conversations live in PostgreSQL (pgdata); visitor
-- application data/files and rolling rate-limit counters stay in their local
-- operational stores for now.

CREATE TABLE IF NOT EXISTS schema_migrations (
    version INTEGER PRIMARY KEY,
    applied_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Visitor accounts are users, not anonymous browser sessions.
CREATE TABLE IF NOT EXISTS visitor_accounts (
    id UUID PRIMARY KEY,
    username TEXT NOT NULL UNIQUE CHECK (username <> ''),
    display_name TEXT NOT NULL CHECK (display_name <> ''),
    password_hash TEXT NOT NULL CHECK (password_hash LIKE 'pbkdf2_sha256$%'),
    disabled BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON TABLE visitor_accounts IS 'Visitor credentials and account state; password_hash is PBKDF2-SHA256 only.';
COMMENT ON COLUMN visitor_accounts.username IS 'NFKC + casefold normalized lookup key, unique across the site.';

-- Normalized entitlements keep app grants queryable and avoid comma-separated lists.
CREATE TABLE IF NOT EXISTS visitor_account_apps (
    account_id UUID NOT NULL REFERENCES visitor_accounts(id) ON DELETE CASCADE,
    app_id TEXT NOT NULL CHECK (app_id ~ '^[a-z0-9][a-z0-9-]{0,31}$'),
    PRIMARY KEY (account_id, app_id)
);

CREATE INDEX IF NOT EXISTS visitor_account_apps_app_idx ON visitor_account_apps (app_id);

-- One conversation per browser session; anonymous sessions are allowed.
CREATE TABLE IF NOT EXISTS agent_conversations (
    id UUID PRIMARY KEY,
    client_session_id TEXT NOT NULL UNIQUE CHECK (client_session_id <> ''),
    visitor_account_id UUID REFERENCES visitor_accounts(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_active_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON TABLE agent_conversations IS 'One row per browser chat session; visitor_account_id is set only for a logged-in visitor.';
COMMENT ON COLUMN agent_conversations.client_session_id IS 'The signed browser session nonce, not a user identity.';

CREATE INDEX IF NOT EXISTS agent_conversations_visitor_idx
    ON agent_conversations (visitor_account_id, last_active_at DESC);

-- One row per completed or failed assistant turn. request_id makes retries idempotent.
CREATE TABLE IF NOT EXISTS agent_turns (
    id UUID PRIMARY KEY,
    conversation_id UUID NOT NULL REFERENCES agent_conversations(id) ON DELETE CASCADE,
    request_id TEXT NOT NULL UNIQUE CHECK (request_id <> ''),
    user_message TEXT NOT NULL CHECK (user_message <> ''),
    assistant_message TEXT,
    status TEXT NOT NULL CHECK (status IN ('completed', 'error', 'cancelled', 'timeout')),
    error_code TEXT,
    desktop_action TEXT,
    model TEXT,
    latency_ms INTEGER,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    finished_at TIMESTAMPTZ
);

COMMENT ON TABLE agent_turns IS 'Per-request audit of one user message and the final assistant answer; never stores intermediate drafts.';
COMMENT ON COLUMN agent_turns.request_id IS 'Frontend X-Request-ID; unique so a retry cannot double-insert.';

CREATE INDEX IF NOT EXISTS agent_turns_conversation_created_idx
    ON agent_turns (conversation_id, created_at DESC);
CREATE INDEX IF NOT EXISTS agent_turns_created_idx
    ON agent_turns (created_at DESC);

INSERT INTO schema_migrations (version) VALUES (1)
ON CONFLICT (version) DO NOTHING;
